import{s as a}from"./auth.DjmdFsHC.js";document.getElementById("magic-form").addEventListener("submit",async t=>{t.preventDefault();const s=new FormData(t.target),n=document.getElementById("form-error"),i=document.getElementById("form-sent"),e=document.getElementById("magic-submit");n.classList.add("hidden"),i.classList.add("hidden"),e.disabled=!0,e.textContent="Sending...";const{error:o}=await a(s.get("email"),s.get("name"),window.location.origin+"/account/orders");if(e.disabled=!1,e.textContent="Email me a sign-in link",o){n.textContent=o.message,n.classList.remove("hidden");return}i.textContent="Check your inbox! Click the link we sent to finish creating your account.",i.classList.remove("hidden"),t.target.reset()});
